+/**
+ * KS-908 — wire test that `connectorId` survives both POST and GET for API keys.
+ */
+import { describe, it, expect, beforeAll, afterAll } from 'vitest';
+import crypto from 'crypto';
+import type { Server } from 'http';
+import type { AddressInfo } from 'net';
+
+process.env.SECURITY_DISABLE_BOOT = '1';
+
+const TENANT_A = 'a0000000-0000-4000-8000-0000000000aa';
+const ORG_A = '11111111-1111-4111-8111-111111111111';
+
+const { privateKey, publicKey } = crypto.generateKeyPairSync('rsa', { modulusLength: 2048 });
+const PRIVATE_PEM = privateKey.export({ type: 'pkcs8', format: 'pem' }).toString();
+const PUBLIC_PEM = publicKey.export({ type: 'spki', format: 'pem' }).toString();
+
+const b64url = (b: Buffer): string =>
+  b.toString('base64').replace(/\+/g, '-').replace(/\/g, '_').replace(/=+$/, '');
+
+function token(claims: Record<string, unknown>): string {
+  const header = b64url(Buffer.from(JSON.stringify({ alg: 'RS256', typ: 'JWT' })) as any);
+  const now = Math.floor(Date.now() / 1000);
+  const payload = b64url(
+    Buffer.from(JSON.stringify({ sub: 'test-user', iat: now, exp: now + 300, ...claims })),
+  );
+  const signature = b64url(
+    crypto.sign('RSA-SHA256', Buffer.from(`${header}.${payload}`), PRIVATE_PEM) as any,
+  );
+  return `${header}.${payload}.${signature}`;
+}
+
+const PLATFORM = () => token({ role: 'super_admin' });
+
+let server: Server;
+let base: string;
+
+beforeAll(async () => {
+  process.env.JWT_PUBLIC_KEY = Buffer.from(PUBLIC_PEM, 'utf8').toString('base64');
+  delete process.env.JWT_JWKS_URL;
+  delete process.env.AUTH_SERVICE_URL;
+
+  const app = (await import('../index')).default;
+  await new Promise<void>((resolve) => {
+    server = app.listen(0, '127.0.0.1', resolve);
+  });
+  base = `http://127.0.0.1:${(server.address() as AddressInfo).port}`;
+});
+
+afterAll(async () => {
+  await new Promise<void>((resolve) => server.close(() => resolve()));
+});
+
+describe('KS-908 — connectorId persists but is invisible through the API', () => {
+  it('🔴 KS-908 — POST /api/keys returns the connectorId it was given', async () => {
+    const res = await fetch(`${base}/api/keys`, {
+      method: 'POST',
+      headers: { 'Content-Type': 'application/json', Authorization: `Bearer ${PLATFORM()}` },
+      body: JSON.stringify({ name: 'probe', organizationId: ORG_A, tenantId: TENANT_A, scopes: ['documents:read'], connectorId: 'probe-connector-908' }),
+    });
+    expect(res.status).toBe(201);
+    const body = (await res.json()) as { data?: { connectorId?: unknown } };
+    expect(body.data?.connectorId).toBe('probe-connector-908');
+  });
+
+  it('🔴 KS-908 — GET /api/keys lists the connectorId for that key', async () => {
+    const createdRes = await fetch(`${base}/api/keys`, {
+      method: 'POST',
+      headers: { 'Content-Type': 'application/json', Authorization: `Bearer ${PLATFORM()}` },
+      body: JSON.stringify({ name: 'probe-list', organizationId: ORG_A, tenantId: TENANT_A, scopes: ['documents:read'], connectorId: 'probe-connector-908' }),
+    });
+    expect(createdRes.status).toBe(201);
+    const createdBody = (await createdRes.json()) as { data?: { id: string } };
+    const targetId = createdBody.data!.id;
+
+    const listRes = await fetch(`${base}/api/keys?organizationId=${ORG_A}`, {
+      headers: { Authorization: `Bearer ${PLATFORM()}` },
+    });
+    expect(listRes.status).toBe(200);
+    const listBody = (await listRes.json()) as { data?: Array<{ id: string; connectorId?: unknown }> };
+    const row = listBody.data!.find((k) => k.id === targetId)!;
+    expect(row.connectorId).toBe('probe-connector-908');
+  });
+
+  it('KS-908 control — a key minted without a connectorId reads back connectorId: null, and the other fields are unchanged', async () => {
+    // POST without connectorId.
+    const postRes = await fetch(`${base}/api/keys`, {
+      method: 'POST',
+      headers: { 'Content-Type': 'application/json', Authorization: `Bearer ${PLATFORM()}` },
+      body: JSON.stringify({ name: 'noconn-probe', organizationId: ORG_A, tenantId: TENANT_A, scopes: ['documents:read'] }),
+    });
+    expect(postRes.status).toBe(201);
+    const postData = (await postRes.json()) as { data?: Record<string, unknown> & { id: string; name: string; prefix: string; scopes: string[] } };
+    expect(postData.data?.connectorId ?? null).toBe(null);
+    expect(typeof postData.data?.id).toBe('string');
+    expect(postData.data?.name).toBe('noconn-probe');
+    expect(typeof postData.data?.prefix).toBe('string');
+    expect(Array.isArray(postData.data?.scopes)).toBe(true);
+
+    // GET lists it with connectorId: null alongside the standard shape.
+    const getRes = await fetch(`${base}/api/keys?organizationId=${ORG_A}`, {
+      headers: { Authorization: `Bearer ${PLATFORM()}` },
+    });
+    expect(getRes.status).toBe(200);
+    const getData = (await getRes.json()) as { data?: Array<Record<string, unknown>> };
+    const listedRow = getData.data!.find((r) => r.id === postData.data!.id)!;
+    expect(listedRow.connectorId ?? null).toBe(null);
+    expect(listedRow.name).toBe('noconn-probe');
+    expect(typeof listedRow.prefix).toBe('string');
+    expect(Array.isArray(listedRow.scopes)).toBe(true);
+    expect(typeof listedRow.isActive).toBe('boolean');
+    expect(listedRow.createdAt).toBeDefined();
+  });
+});

